<?php require_once __DIR__ . '/../includes/demo_helpers.php'; require_login(); $post = $demoPosts[(int) ($_GET['id'] ?? 0)] ?? null; demo_page_start('Post'); ?>
<section class="sc-feed"><p class="sc-eyebrow">Post</p><?php if (!$post): ?><div class="sc-card sc-empty"><h1>Post not found</h1><p>This demo post is unavailable.</p></div><?php else: ?><?php demo_post($post, false); ?><section class="sc-card"><h2>Comments</h2><?php foreach ($demoComments as $comment): ?><p><strong>@<?= e($comment['username']) ?></strong> <?= e($comment['content']) ?></p><?php endforeach; ?><form class="sc-form" action="#" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label for="comment">Add a comment</label><textarea id="comment" rows="3"></textarea><button class="sc-btn sc-btn--primary" type="submit">Comment</button></form></section><?php endif; ?><p class="sc-demo-label">Demo data · likes and comments are UI-only.</p></section>
<?php demo_page_end(); ?>
